              "In January 1915 Armand was planning a pamphlet for working women (it never appeared). In his letter of 17 January Lenin advised her to drop section 3 of the plan, the '(women's) demand for freedom of love', saying it would turn out to be a bourgeois rather than a proletarian demand.",
