              "During the civil war, she explains, 'wingless Eros' prevailed: sexual attraction that comes and goes easily without emotional bonds, because a fighting class had to save its psychological energy for the revolution. Now, as things calm down, 'winged Eros', attraction interwoven with feeling, is reclaiming its rights, and the young people's interest is not a symptom of 'decline'.",
              "Working-class ideology, she says, does not care whether love takes the form of a long, formalised union or a passing relationship, but it is strict about the content. Wingless Eros exhausts the energy for work, impoverishes the soul and rests on women's dependence on men, so it will be opposed more severely than bourgeois morality ever did.",
              "Her 'love-comradeship' rests on three principles: equality, mutual recognition of the other's rights without claiming to own the other's heart, and comradely sensitivity; and the love of two people is subordinated to a stronger 'love-duty' to the collective. Hence her contrast: bourgeois morality demanded 'all for the loved one', proletarian morality 'all for the collective'."
