                "en": "Beauvoir grants that Engels's synthesis is an advance on the biological and psychoanalytic views she has examined, yet finds that it slurs over the most important problems. It gives no account of how the pivot of all history, the passage from communal ownership to private property, came about, and it is not clear why private property must have enslaved women. Historical materialism takes for granted the interest that binds man to property; she asks where that interest has its source. Her answer is existentialist: the existent grasps himself only in alienated form and finds himself again in goods, which calls for an ontological infrastructure, not the tool alone. The sexual division of labour could have been a friendly association; had consciousness not held the original category of the Other and an aspiration to dominate it, the bronze tool could not have caused women's oppression."
