                "ko": "보부아르는 결론에서 남녀가 평등한 세계는 쉽게 그려 볼 수 있다며, 그것이 바로 소비에트 혁명이 약속한 것이라고 씁니다. 같은 교육과 같은 노동 조건과 임금, 자유로운 합의에 바탕한 결혼, 피임과 낙태의 허용, 혼인 안팎 아이의 같은 권리, 국가가 부담하는 출산 휴가가 그 내용이었습니다. 그러면서 법과 제도, 관습과 여론까지 바꾸는 것만으로 충분한지 묻습니다. 그녀의 답은 경제적 조건이 여성 변화의 근본 요인이었고 지금도 그렇지만, 그것이 약속하고 요구하는 도덕적·사회적·문화적 귀결을 낳기 전에는 새로운 여성이 나타날 수 없다는 것입니다. 그 귀결은 아직 어디서도, 소련에서도 실현되지 않았다고 봅니다. 그래서 그녀를 경제를 무시한 관념론자로 읽는 것은 맞지 않고, 쟁점은 경제 변화의 충분성에 있습니다.",
