                "en": "Mitchell notes that the woman question, though part of the movement's classical heritage, had nearly vanished from socialists' concerns by the mid-twentieth century, and traces part of the cause to weaknesses in the classics themselves. The early Marx treated woman as an abstract symbol, an index of general emancipation; the later Marx submerged women in his analysis of the family. Engels, relying on Morgan's inaccurate anthropology, had valuable insights but reduced the problem of woman to her capacity to work, making physiological weakness the primary cause of oppression and ability to work the key to liberation. Bebel added a biological element, the maternal function, but could do no more than state that sexual equality was impossible without socialism; Lenin inherited a tradition that simply equated socialism with women's liberation a priori. Women's liberation thus remained a normative ideal, an adjunct to socialist theory, not structurally integrated into it."
