                "en": "Mitchell holds that past socialist theory failed to differentiate woman's condition into its constituent structures, and rejects both deducing it from the economy (Engels) and equating it symbolically with society (the early Marx). Each sector has its own autonomous reality but is determined by the economy only in the last instance; because the sectors move at different paces, contradictions sometimes cancel and sometimes reinforce one another, so woman's condition is always 'overdetermined'. A note in the 1966 version credits the concept to Althusser. In the conclusion she says all four structures must be transformed and gives historical cases: the vote completed formal legal equality but left women's socio-economic situation virtually unchanged; the Soviet Union's 1920s legislation freeing sexuality was followed by a Stalinist return to inheritance, restricted divorce and banned abortion; China's stress on liberating women in production came with a tremendous repression of sexuality and a rigorous puritanism."
